    var mxb_w2 = 5769; mxb_w2 = mxb_w2/10000;
    var mxb_ka = 75;   mxb_ka = mxb_ka/1000;
    var mxb_kb = 54;   mxb_kb = mxb_kb/100;
    var mxb_a2 = 2;    mxb_a2 = mxb_a2/10;
    var mxb_a8 = 8;    mxb_a8 = mxb_a8/10;
